use wordcount::{word_count, top_words};
use std::collections::HashMap;

#[test]
fn test_word_count_basic() {
    let counts = word_count("hello world hello");
    assert_eq!(counts.get("hello"), Some(&2));
    assert_eq!(counts.get("world"), Some(&1));
}

#[test]
fn test_word_count_case_insensitive() {
    let counts = word_count("Hello HELLO hello");
    assert_eq!(counts.get("hello"), Some(&3));
}

#[test]
fn test_word_count_empty() {
    let counts = word_count("");
    assert!(counts.is_empty());
}

#[test]
fn test_top_words_basic() {
    let top = top_words("a b a c a b", 2);
    assert_eq!(top[0], "a");
    assert_eq!(top[1], "b");
}

#[test]
fn test_top_words_alpha_tiebreak() {
    // "apple" and "banana" both appear once; alpha order: apple < banana
    let top = top_words("apple banana", 2);
    assert_eq!(top[0], "apple");
    assert_eq!(top[1], "banana");
}

